    // Header Hardware Tag
    drawRoundedRect(ctx, cardX + 30, cardY + 30, cardW - 60, 54, 12);
    ctx.fillStyle = hexAlpha(st.color, 0.2);
    ctx.fill();
    ctx.fillStyle = st.color;
    ctx.font = "bold 24px monospace";
    ctx.textAlign = "center";
    ctx.fillText(st.hw, cardX + cardW / 2, cardY + 65);

    // Ilustrasi Tengah
    const midX = cardX + cardW / 2;
