    ctx.beginPath();
    ctx.arc(midX, midY, 74, 0, Math.PI * 2);
    ctx.fillStyle = hexAlpha(st.color, 0.14);
    ctx.fill();
    ctx.strokeStyle = st.color;
    ctx.lineWidth = 2.5;
    ctx.stroke();

    // Simbol Visual di Dalam Lingkaran
    ctx.fillStyle = "#ffffff";
    ctx.font = "bold 28px monospace";
    ctx.fillText(st.icon, midX, midY + 10);

    // Nama Analogi Dapur
