// Adegan 8: VGA / GPU = Tim Seniman Dekorasi Makanan
function drawScene8GpuArtists(ctx, time) {
  const topY = 235;

  // Kartu Kiri: Kartu Grafis Dual/Triple Fan Modern
  const gpuX = 120;
  const gpuW = 820;
  const gpuH = 490;
  drawRoundedRect(ctx, gpuX, topY, gpuW, gpuH, 24);
  ctx.fillStyle = rgbaStr(24, 12, 28, 0.92);
  ctx.fill();
  ctx.strokeStyle = "#f43f5e";
  ctx.lineWidth = 3;
  ctx.stroke();

  ctx.fillStyle = "#f43f5e";
  ctx.font = "bold 26px sans-serif";
  ctx.fillText("VGA / GPU (GRAPHICS PROCESSING UNIT)", gpuX + 36, topY + 52);

  // Ilustrasi Shroud GPU dengan 2 Kipas Berputar
  const shroudX = gpuX + 60;
  const shroudY = topY + 95;
  const shroudW = 700;
  const shroudH = 260;
  drawRoundedRect(ctx, shroudX, shroudY, shroudW, shroudH, 20);
  ctx.fillStyle = "#18181b";
  ctx.fill();
  ctx.strokeStyle = "#fb7185";
  ctx.lineWidth = 3;
  ctx.stroke();

  [shroudX + 200, shroudX + 500].forEach((fanX, idx) => {
    const fanY = shroudY + shroudH / 2;
    ctx.beginPath();
    ctx.arc(fanX, fanY, 95, 0, Math.PI * 2);
    ctx.fillStyle = "#09090b";
    ctx.fill();
    ctx.strokeStyle = "#f43f5e";
    ctx.lineWidth = 3;
    ctx.stroke();

    // Bilah Kipas Berputar
    for (let b = 0; b < 9; b++) {
      const ang = time * 6 + (b * Math.PI * 2) / 9 + idx;
      ctx.beginPath();
      ctx.moveTo(fanX, fanY);
      ctx.lineTo(fanX + Math.cos(ang) * 86, fanY + Math.sin(ang) * 86);
      ctx.strokeStyle = hexAlpha("#fb7185", 0.75);
      ctx.lineWidth = 6;
      ctx.stroke();
    }

    ctx.beginPath();
    ctx.arc(fanX, fanY, 24, 0, Math.PI * 2);
    ctx.fillStyle = "#f43f5e";
    ctx.fill();
  });

  ctx.fillStyle = "#ffe4e6";
  ctx.font = "bold 22px sans-serif";
  ctx.fillText(" ANALOGI DAPUR: TIM SENIMAN DEKORASI MAKANAN", gpuX + 60, topY + 410);
  ctx.fillStyle = "#fda4af";
  ctx.font = "19px sans-serif";
  ctx.fillText(
    "Mengambil alih tugas melukis detail piring rumit yang membuat Kepala Koki kewalahan.",
    gpuX + 60,
    topY + 448
  );

  // Kartu Kanan: Visualisasi Piring Dekorasi Piksel Presisi Tinggi
  const artX = 990;
  const artW = 810;
  drawRoundedRect(ctx, artX, topY, artW, gpuH, 24);
  ctx.fillStyle = rgbaStr(20, 14, 32, 0.92);
  ctx.fill();
  ctx.strokeStyle = "#fb7185";
  ctx.lineWidth = 2.5;
  ctx.stroke();

  ctx.fillStyle = "#fb7185";
  ctx.font = "bold 26px sans-serif";
  ctx.fillText("DEKORASI DETAIL VISUAL SECARA CEPAT", artX + 36, topY + 52);

  // Mandala / Pola Geometris Plating Makanan Presisi Tinggi
  const plateX = artX + artW / 2;
  const plateY = topY + 275;
  for (let ring = 4; ring >= 1; ring--) {
    ctx.beginPath();
    ctx.arc(plateX, plateY, ring * 38, 0, Math.PI * 2);
    ctx.strokeStyle = ring % 2 === 0 ? "#f43f5e" : "#a855f7";
    ctx.lineWidth = 3;
    ctx.stroke();
  }
  for (let p = 0; p < 12; p++) {
    const a = time * 0.8 + (p * Math.PI * 2) / 12;
    const px = plateX + Math.cos(a) * 115;
    const py = plateY + Math.sin(a) * 115;
    ctx.beginPath();
    ctx.arc(px, py, 12, 0, Math.PI * 2);
    ctx.fillStyle = p % 2 === 0 ? "#f43f5e" : "#38bdf8";
    ctx.fill();
  }
}

// Adegan 9: Ribuan Inti Paralel, Poligon 3D, Ray Tracing & Jutaan Piksel
function drawScene9RayTracingParallel(ctx, time) {
  const topY = 235;

  // Kiri: Matriks Ribuan Inti Kecil Paralel (Shader Cores)
  const leftX = 110;
  const leftW = 820;
  const boxH = 490;
  drawRoundedRect(ctx, leftX, topY, leftW, boxH, 22);
  ctx.fillStyle = rgbaStr(18, 12, 34, 0.92);
  ctx.fill();
  ctx.strokeStyle = "#ec4899";
  ctx.lineWidth = 2.5;
  ctx.stroke();

  ctx.fillStyle = "#ec4899";
  ctx.font = "bold 25px sans-serif";
  ctx.fillText("RIBUAN INTI KECIL PEMROSESAN PARALEL", leftX + 34, topY + 50);

  const cols = 22;
  const rows = 11;
  const cellW = 31;
  const cellH = 31;
  const startGridX = leftX + 38;
  const startGridY = topY + 78;

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const wave = 0.5 + 0.5 * Math.sin(time * 4 + c * 0.35 + r * 0.45);
      ctx.fillStyle =
        wave > 0.65
          ? rgbaStr(236, 72, 153, wave)
          : rgbaStr(139, 92, 246, wave * 0.7);
      ctx.fillRect(startGridX + c * (cellW + 3), startGridY + r * (cellH + 3), cellW, cellH);
    }
  }

  ctx.fillStyle = "#f9a8d4";
  ctx.font = "19px sans-serif";
  ctx.fillText(
    "Memproses jutaan piksel ke layar monitor secara serentak dalam hitungan milidetik",
    leftX + 38,
    topY + 468
  );

  // Kanan: Pipeline 3D Polygon + Pantulan Cahaya (Ray Tracing) + 4K Render
  const rightX = 970;
  const rightW = 840;
  drawRoundedRect(ctx, rightX, topY, rightW, boxH, 22);
  ctx.fillStyle = rgbaStr(14, 16, 36, 0.92);
  ctx.fill();
  ctx.strokeStyle = "#8b5cf6";
  ctx.lineWidth = 2.5;
  ctx.stroke();

  ctx.fillStyle = "#c084fc";
  ctx.font = "bold 25px sans-serif";
  ctx.fillText("POLIGON 3D, RAY TRACING & TEKSTUR OBJEK", rightX + 34, topY + 50);

  // Simulasi Sumber Cahaya & Pantulan Sinar (Ray Tracing)
  const lightX = rightX + 140;
  const lightY = topY + 150;
  const objX = rightX + 430;
  const objY = topY + 290;
  const screenX = rightX + 710;
  const screenY = topY + 180;

  // Sinar datang & pantulan
  ctx.strokeStyle = "#fde047";
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(lightX, lightY);
  ctx.lineTo(objX, objY);
  ctx.lineTo(screenX, screenY);
  ctx.stroke();

  // Sumber Cahaya
  ctx.beginPath();
  ctx.arc(lightX, lightY, 26, 0, Math.PI * 2);
  ctx.fillStyle = "#fde047";
  ctx.fill();
  ctx.fillStyle = "#fef08a";
  ctx.font = "bold 16px monospace";
  ctx.fillText("LIGHT RAY", lightX - 42, lightY + 50);

  // Objek Poligon 3D
  ctx.beginPath();
  for (let k = 0; k < 6; k++) {
    const a = time * 1.2 + (k * Math.PI) / 3;
    const px = objX + Math.cos(a) * 78;
    const py = objY + Math.sin(a) * 78;
    if (k === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.fillStyle = rgbaStr(236, 72, 153, 0.28);
  ctx.fill();
  ctx.strokeStyle = "#ec4899";
  ctx.lineWidth = 3;
  ctx.stroke();

  // Badge Beban Kerja Berat
  const workloads = ["GAME AAA ULTRA", "RENDERING VIDEO 4K", "PEMODELAN 3D"];
  workloads.forEach((w, idx) => {
    const wx = rightX + 40 + idx * 260;
    const wy = topY + 410;
    drawRoundedRect(ctx, wx, wy, 240, 52, 10);
    ctx.fillStyle = rgbaStr(139, 92, 246, 0.25);
    ctx.fill();
    ctx.strokeStyle = "#c084fc";
    ctx.stroke();
    ctx.fillStyle = "#ffffff";
    ctx.font = "bold 18px sans-serif";
    ctx.textAlign = "center";
    ctx.fillText(w, wx + 120, wy + 33);
  });
  ctx.textAlign = "left";
}

