// ============================================================================
// 6. HEADER ATAS, SUBTITLE NARASI DINAMIS, & PROGRESS BAR BAWAH
// ============================================================================
function drawTopHeader(ctx, scene, time, totalDuration) {
  // Tag Kategori Pojok Kiri Atas
  drawRoundedRect(ctx, 110, 48, 520, 44, 10);
  ctx.fillStyle = hexAlpha(scene.themeColor, 0.2);
  ctx.fill();
  ctx.strokeStyle = scene.themeColor;
  ctx.lineWidth = 2;
  ctx.stroke();

  ctx.fillStyle = scene.themeColor;
  ctx.font = "bold 20px monospace";
  ctx.fillText(scene.tag, 132, 77);

  // Badge Timecode & Channel Kanan Atas
  drawRoundedRect(ctx, WIDTH - 430, 48, 320, 44, 10);
  ctx.fillStyle = rgbaStr(15, 23, 42, 0.85);
  ctx.fill();
  ctx.strokeStyle = hexAlpha("#94a3b8", 0.4);
  ctx.stroke();

  const curMin = String(Math.floor(time / 60)).padStart(2, "0");
  const curSec = String(Math.floor(time % 60)).padStart(2, "0");
  const totMin = String(Math.floor(totalDuration / 60)).padStart(2, "0");
  const totSec = String(Math.floor(totalDuration % 60)).padStart(2, "0");

  ctx.fillStyle = "#e2e8f0";
  ctx.font = "bold 19px monospace";
  ctx.fillText(`PROF. ILMI // ${curMin}:${curSec} / ${totMin}:${totSec}`, WIDTH - 408, 77);

  // Judul Utama & Subjudul Scene
  ctx.fillStyle = "#ffffff";
  ctx.font = "bold 46px sans-serif";
  ctx.fillText(scene.title, 110, 148);

  ctx.fillStyle = "#94a3b8";
  ctx.font = "24px sans-serif";
  ctx.fillText(scene.subtitle, 110, 188);
}

function drawSubtitleAndTelemetry(ctx, scene, localProg, time, totalDuration) {
  // Kotak Subtitle Narasi Aktif
  const subX = 110;
  const subY = 765;
  const subW = 1700;
  const subH = 185;

  drawRoundedRect(ctx, subX, subY, subW, subH, 20);
  ctx.fillStyle = rgbaStr(7, 12, 24, 0.92);
  ctx.fill();
  ctx.lineWidth = 2;
  ctx.strokeStyle = hexAlpha(scene.themeColor, 0.65);
  ctx.stroke();

  // Audio Waveform Visualizer di Sisi Kiri Kotak Subtitle
  const waveBaseX = subX + 36;
  const waveCenterY = subY + subH / 2;
  for (let b = 0; b < 12; b++) {
    const barH = 18 + Math.abs(Math.sin(time * 9 + b * 0.7)) * 75;
    ctx.fillStyle = b % 2 === 0 ? scene.themeColor : scene.secondaryColor;
    drawRoundedRect(ctx, waveBaseX + b * 12, waveCenterY - barH / 2, 8, barH, 4);
    ctx.fill();
  }

  // Bungkus kata-kata narasi dengan highlight kata yang sedang diucapkan
  const words = scene.narration.split(" ");
  const activeWordIndex = Math.floor(clamp(localProg, 0, 0.999) * words.length);

  ctx.font = "bold 27px sans-serif";
  const maxTextWidth = subW - 240;
  const startTextX = subX + 205;
  let lines = [];
  let currentLine = [];
  let currentWidth = 0;

  words.forEach((word, idx) => {
    const wordW = ctx.measureText(word + " ").width;
    if (currentWidth + wordW > maxTextWidth && currentLine.length > 0) {
      lines.push(currentLine);
      currentLine = [];
      currentWidth = 0;
    }
    currentLine.push({ word, idx, width: wordW });
    currentWidth += wordW;
  });
  if (currentLine.length > 0) lines.push(currentLine);

  // Tampilkan maksimal 3 baris di sekitar kata aktif agar selalu terbaca jelas
  let activeLineIdx = 0;
  lines.forEach((line, lIdx) => {
    if (line.some((w) => w.idx === activeWordIndex)) {
      activeLineIdx = lIdx;
    }
  });

  const startLine = Math.max(0, Math.min(activeLineIdx - 1, lines.length - 3));
  const visibleLines = lines.slice(startLine, startLine + 3);

  visibleLines.forEach((line, rowOffset) => {
    let cursorX = startTextX;
    const rowY = subY + 58 + rowOffset * 44;
    line.forEach((item) => {
      if (item.idx === activeWordIndex) {
        ctx.fillStyle = scene.themeColor;
      } else if (item.idx < activeWordIndex) {
        ctx.fillStyle = "#ffffff";
      } else {
        ctx.fillStyle = "#94a3b8";
      }
      ctx.fillText(item.word, cursorX, rowY);
      cursorX += item.width;
    });
  });

  // Footer Metrics & Progress Bar Global
  const footY = 978;
  scene.metrics.forEach((m, i) => {
    const mx = 110 + i * 575;
    drawRoundedRect(ctx, mx, footY, 545, 56, 12);
    ctx.fillStyle = rgbaStr(15, 23, 42, 0.85);
    ctx.fill();
    ctx.strokeStyle = hexAlpha(scene.themeColor, 0.45);
    ctx.lineWidth = 1.5;
    ctx.stroke();

    ctx.fillStyle = "#94a3b8";
    ctx.font = "bold 17px monospace";
    ctx.fillText(`${m.label}:`, mx + 20, footY + 34);

    ctx.fillStyle = "#ffffff";
    ctx.font = "bold 19px sans-serif";
    ctx.fillText(m.value, mx + 215, footY + 34);

    ctx.fillStyle = scene.themeColor;
    ctx.font = "bold 16px monospace";
    ctx.fillText(`[${m.status}]`, mx + 415, footY + 34);
  });

  // Garis Progress Video di Tepi Bawah Layar
  const globalProg = clamp(time / totalDuration, 0, 1);
  ctx.fillStyle = "#0f172a";
  ctx.fillRect(0, HEIGHT - 12, WIDTH, 12);
  ctx.fillStyle = scene.themeColor;
  ctx.fillRect(0, HEIGHT - 12, WIDTH * globalProg, 12);
}

// ============================================================================
// 7. DISPATCHER RENDER FRAME UTAMA
// ============================================================================
function renderFrame(ctx, time, totalDuration) {
  let activeScene = SCENES[SCENES.length - 1];
  for (const s of SCENES) {
    if (time >= s.startTime && time <= s.endTime) {
      activeScene = s;
      break;
    }
  }

  const localProg = clamp(
    (time - activeScene.startTime) / Math.max(0.001, activeScene.duration),
    0,
    1
  );

  drawCyberBackground(ctx, time, activeScene);
  drawTopHeader(ctx, activeScene, time, totalDuration);

  switch (activeScene.id) {
    case 0:
      drawScene0Hook(ctx, time, localProg, activeScene);
      break;
    case 1:
      drawScene1ThreeBrains(ctx, time, localProg);
      break;
    case 2:
      drawScene2ProfesorIlmi(ctx, time, localProg);
      break;
    case 3:
      drawScene3KitchenAnalogy(ctx, time, localProg);
      break;
    case 4:
      drawScene4CpuChef(ctx, time);
      break;
    case 5:
      drawScene5CoresClock(ctx, time);
      break;
    case 6:
      drawScene6RamWorkbench(ctx, time);
      break;
    case 7:
      drawScene7RamCapacity(ctx, time);
      break;
    case 8:
      drawScene8GpuArtists(ctx, time);
      break;
    case 9:
      drawScene9RayTracingParallel(ctx, time);
      break;
    case 10:
    default:
      drawScene10ConclusionBalance(ctx, time);
      break;
  }

  drawSubtitleAndTelemetry(ctx, activeScene, localProg, time, totalDuration);
}

// ============================================================================
// 8. PIPELINE EKSEKUSI & RENDERING FFMPEG (TANPA ATEMPO=1.18)
// ============================================================================
async function main() {
  console.log("============================================================");
  console.log(" MEMULAI RENDER VIDEO: PROFESOR ILMI - CPU, RAM, & VGA/GPU");
  console.log("============================================================");

  const { masterAudioPath, totalDuration } = await prepareAudioTrack();
  const totalFrames = Math.ceil(totalDuration * FPS);

  console.log(`[INFO] Resolusi: ${WIDTH}x${HEIGHT} @ ${FPS} FPS`);
  console.log(`[INFO] Durasi Total: ${totalDuration.toFixed(2)} detik (${totalFrames} frame)`);

  const canvas = createCanvas(WIDTH, HEIGHT);
  const ctx = canvas.getContext("2d");

  // Spawn FFmpeg dengan input rawvideo RGBA dari pipe stdin + master audio
  // Catatan: Tidak menggunakan filter atempo=1.18 sesuai instruksi
  const ffmpegArgs = [
    "-y",
    "-f",
    "rawvideo",
    "-pix_fmt",
    "rgba",
    "-s",
    `${WIDTH}x${HEIGHT}`,
    "-r",
    String(FPS),
    "-i",
    "pipe:0",
    "-i",
    masterAudioPath,
    "-c:v",
    "libx264",
    "-pix_fmt",
    "yuv420p",
    "-preset",
    "veryfast",
    "-crf",
    "20",
    "-c:a",
    "aac",
    "-b:a",
    "192k",
    "-shortest",
    OUTPUT_VIDEO,
  ];

  const ffmpegProc = spawn("ffmpeg", ffmpegArgs, {
    stdio: ["pipe", "inherit", "inherit"],
  });

  for (let frameIdx = 0; frameIdx < totalFrames; frameIdx++) {
    const currentTime = frameIdx / FPS;
    renderFrame(ctx, currentTime, totalDuration);

    // Ambil buffer RGBA murni dari @napi-rs/canvas (atau fallback node-canvas)
    const rawBuffer =
      typeof canvas.data === "function"
        ? canvas.data()
        : canvas.toBuffer("raw");

    const canWrite = ffmpegProc.stdin.write(rawBuffer);
    if (!canWrite) {
      await new Promise((resolve) => ffmpegProc.stdin.once("drain", resolve));
    }

    if (frameIdx % (FPS * 10) === 0 || frameIdx === totalFrames - 1) {
      const pct = (((frameIdx + 1) / totalFrames) * 100).toFixed(1);
      console.log(`[RENDER] Frame ${frameIdx + 1}/${totalFrames} (${pct}%)`);
    }
  }

  ffmpegProc.stdin.end();

  await new Promise((resolve, reject) => {
    ffmpegProc.on("close", (code) => {
      if (code === 0) resolve();
      else reject(new Error(`FFmpeg keluar dengan kode ${code}`));
    });
    ffmpegProc.on("error", reject);
  });

  console.log(`[SUKSES] Video selesai dirender ke ${OUTPUT_VIDEO}`);
}


